#include "strata/kernels/fused_gdn.hpp"            // I2 (GDN mixer): fused_gdn_conv_l2 / fused_gdn_ab
#include "strata/kernels/native_gdn_preprocess.hpp" // I2 (GDN mixer): native_gdn_conv_silu / native_gdn_l2_norm
