    case_gather_rows_entry(ctx, dir);            // gather_rows       -> gather_rows.spv      (mtp.cpp:450)
    case_scatter_rows_f32_entry(ctx, dir);       // scatter_rows_f32  -> scatter_rows_f32.spv (peer_experts.cpp:241)
    case_cvec_apply_entry(ctx, dir);             // cvec_apply        -> cvec_apply.spv       (layer.cpp:1330)
    case_add_inplace_entry(ctx, dir);            // add_inplace       -> add.spv              (expert_source.cpp:2353)
    case_f32_to_f16_bulk_entry(ctx, dir);        // f32_to_f16_bulk   -> f32_to_f16.spv       (no src/core site)
    // I2 (the GDN / DeltaNet MIXER): the first six GDN kernels the mixer `gdn_layer` reaches, in call-site order
    // (layer.cpp:250/253/255/266/269/287).  APPENDED last for the same shared-RNG reason as every batch above.
    case_fused_gdn_conv_l2_entry(ctx, dir);      // fused_gdn_conv_l2   -> fused_gdn_conv_l2.spv   (layer.cpp:250)
    case_native_gdn_conv_silu_entry(ctx, dir);   // native_gdn_conv_silu-> native_gdn_conv_silu.spv(layer.cpp:253)
    case_gdn_conv_step_entry(ctx, dir);          // gdn_conv_step       -> gdn_conv_step.spv       (layer.cpp:255)
    case_native_gdn_l2_norm_entry(ctx, dir);     // native_gdn_l2_norm  -> native_gdn_l2_norm.spv  (layer.cpp:266)
    case_gdn_l2_norm_entry(ctx, dir);            // gdn_l2_norm         -> gdn_l2_norm.spv         (layer.cpp:269)
    case_fused_gdn_ab_entry(ctx, dir);           // fused_gdn_ab        -> fused_gdn_ab.spv        (layer.cpp:287)
    // I2e (the GDN / DeltaNet MIXER, completed): the REMAINING EIGHT kernels the mixer `gdn_layer` reaches,
    // in call-site order (layer.cpp:296/297/299/308/309/322/324/325; gdn_gate :300 is in elementwise_vk.cpp).
    // APPENDED last for the same shared-RNG reason as every batch above.
    case_native_gdn_beta_gate_entry(ctx, dir);   // native_gdn_beta_gate -> native_gdn_beta_gate.spv (layer.cpp:296)
    case_native_gdn_gate_entry(ctx, dir);        // native_gdn_gate      -> native_gdn_gate.spv      (layer.cpp:297)
    case_gdn_beta_gate_entry(ctx, dir);          // gdn_beta_gate        -> gdn_beta_gate.spv        (layer.cpp:299)
    case_native_gdn_step_entry(ctx, dir);        // native_gdn_step      -> native_gdn_step.spv      (layer.cpp:308)
    case_gdn_step_entry(ctx, dir);               // gdn_step             -> gdn_step.spv             (layer.cpp:309)
    case_fused_gdn_step_norm_entry(ctx, dir);    // fused_gdn_step_norm  -> fused_gdn_step_norm.spv  (layer.cpp:322)
    case_native_gdn_out_norm_entry(ctx, dir);    // native_gdn_out_norm  -> native_gdn_out_norm.spv  (layer.cpp:324)
    case_gdn_out_norm_entry(ctx, dir);           // gdn_out_norm         -> gdn_out_norm.spv         (layer.cpp:325)
    // I3: THE FIRST EIGHT MATVEC / GEMV / KV ENTRY POINTS (vulkan/src/kernels/matvec_vk.cpp), in the order the
    // layer body reaches them.  APPENDED last for the same shared-RNG reason as every batch above.
    case_quantize_q8_K_entry(ctx, dir);          // quantize_q8_K        -> quantize_q8_K.spv      (layer.cpp:236)
    case_quantize_q8_0_entry(ctx, dir);          // quantize_q8_0        -> quantize_q8_0.spv      (layer.cpp:237)
    case_native_quantize_q8_1_entry(ctx, dir);   // native_quantize_q8_1 -> quantize_q8_1.spv      (layer.cpp:150)
    case_native_mmvq_entry(ctx, dir);            // native_mmvq          -> iq*_mmvq.spv (6)      (layer.cpp:151)
    case_kv_append_q4_entry(ctx, dir);           // kv_append_q4_step    -> kv_q4_append.spv       (layer.cpp:935)
    case_kv_gather_q4_entry(ctx, dir);           // kv_gather_q4_step    -> kv_q4_gather.spv       (layer.cpp:985)
    case_quantize_q8_0_scaled_entry(ctx, dir);   // quantize_q8_0_scaled -> quantize_q8_0_scaled.spv (session.cpp:868)
    case_native_q5_k_f32_entry(ctx, dir);        // native_q5_k_f32      -> native_q5_k_f32.spv    (native_head.cpp:78)
    // I4: THE NEXT EIGHT MATVEC / GEMV / KV ENTRY POINTS (vulkan/src/kernels/matvec_vk.cpp), in the order the
    // layer body reaches them (the BF16 GEMVs, the S2 GEMV, and the fp16/int8 KV cache).  APPENDED last for the
    // same shared-RNG reason as every batch above.
    case_bf16_gemv_fp32_mmvf_entry(ctx, dir);    // bf16_gemv_fp32_mmvf  -> bf16_mmvf_f32.spv      (layer.cpp:97)
    case_bf16_gemv_split_entry(ctx, dir);        // bf16_gemv_split      -> bf16_gemv.spv          (layer.cpp:98)
    case_bf16_gemv_entry(ctx, dir);              // bf16_gemv            -> bf16_gemv.spv          (layer.cpp:99)
    case_s2_gemv_q8_entry(ctx, dir);             // s2_gemv_q8           -> s2_gemv_q8.spv         (layer.cpp:166)
    case_kv_append_q8_entry(ctx, dir);           // kv_append_q8_step    -> kv_q8_append.spv       (layer.cpp:934)
    case_kv_append_step_entry(ctx, dir);         // kv_append_step       -> kv_f16_append.spv      (layer.cpp:943)
    case_kv_gather_q8_entry(ctx, dir);           // kv_gather_q8_step    -> kv_q8_gather.spv       (layer.cpp:983)
    case_kv_gather_step_entry(ctx, dir);         // kv_gather_step       -> kv_f16_gather.spv      (layer.cpp:989)
    // THE ATTENTION / QSA / rope ENTRY POINTS (vulkan/src/kernels/qsa_vk.cpp), in the order the non-GDN body
    // `qsa_layer` reaches them (layer.cpp:879/881/882/970/971/1010/1011) plus the router (:370).  APPENDED last
    // for the same shared-RNG reason as every batch above.
    case_native_qsa_rms_norm_weighted_entry(ctx, dir); // native_qsa_rms_norm_weighted -> native_qsa_rms_norm_weighted.spv (layer.cpp:879)
    case_native_rope_apply_entry(ctx, dir);            // native_rope_apply            -> native_rope_apply.spv            (layer.cpp:881)
    case_rope_neox_apply_entry(ctx, dir);              // rope_neox_apply              -> rope_neox.spv                    (layer.cpp:882)
    case_qsa_block_scores_entry(ctx, dir);             // qsa_block_scores             -> qsa_block_scores.spv             (layer.cpp:970)
    case_qsa_block_topk_entry(ctx, dir);               // qsa_block_topk               -> qsa_block_topk.spv               (layer.cpp:971)
    case_native_qsa_gate_apply_entry(ctx, dir);        // native_qsa_gate_apply        -> native_qsa_gate_apply.spv        (layer.cpp:1010)
    case_qsa_gate_apply_f32_entry(ctx, dir);           // qsa_gate_apply_f32           -> qsa_gate_apply_f32.spv           (layer.cpp:1011)
    case_native_router_top10_entry(ctx, dir);          // native_router_top10          -> native_router_top10.spv          (layer.cpp:370)
    case_qsa_decode_attn(ctx, dir);                    // qsa_decode_attn_step         -> qsa_decode_attn.spv              (layer.cpp:980, the DEFAULT)
    // THE PLE / GR SHARED STAGES AND THE MoE ROUTING ROWS (vulkan/src/kernels/ple_vk.cpp), in the order
    // `block_layer_pre`/`block_layer_post` reach them.  APPENDED last for the same shared-RNG reason as every
    // batch above.
    case_gr_write_entry(ctx, dir);               // gr_write            -> gr_write.spv            (layer.cpp:1261/:1195/:1329)
    case_ple_block_entry(ctx, dir);              // ple_block           -> q8_0+s2/bf16 + gnorm/gate/bcast/conv/add3 (layer.cpp:1208)
    case_ple_history_advance_entry(ctx, dir);    // ple_history_advance -> ple_history_advance.spv (layer.cpp:1222)
    case_gr_read_entry(ctx, dir);                // gr_read             -> gr_norm/gr_down/gr_gate/gr_mean/gr_inject (layer.cpp:1255)
    case_router_top10_entry(ctx, dir);           // router_top10        -> router_top10_f32.spv     (layer.cpp:373)
    case_native_moe_combine_entry(ctx, dir);     // native_moe_combine  -> native_moe_combine.spv  (layer.cpp:463, the DEFAULT combine)
    // THE MoE / QSA / GR / PLE TAIL (this batch), in the order the engine's own body reaches them.  APPENDED
    // last for the same shared-RNG reason as every batch above.
    case_qsa_step_fill_entry(ctx, dir);              // qsa_step_fill             (layer.cpp:908, PURE HOST)
    case_indexer_key_append_entry(ctx, dir);         // indexer_key_append        -> indexer_key_append.spv (layer.cpp:948)
    case_fused_gr_supported_entry(ctx, dir);         // fused_gr_supported        (layer.cpp:1189/:1328, PURE HOST)
    case_shared_expert_scratch_bytes_entry(ctx, dir);// shared_expert_scratch_bytes (layer.cpp:347, PURE HOST)
    case_moe_combine_entry(ctx, dir);                // moe_combine               -> moe_combine_f32.spv   (layer.cpp:464)
    case_ngram_rows_entry(ctx, dir);                 // ngram_rows                (layer.cpp:1293, PURE HOST - the PLE hash)
    // THIS BATCH: the two S-family SPLIT GEMV entry points (the pair that BLOCKED `shared_expert`) and the
